impl Solution {
    pub fn max_in_table(n: u32) -> u32 {
        if n == 1 {
            return 1;
        }
        if n == 2 {
            return 3;
        }
        if n == 3 {
            return 7;
        }
        if n == 4 {
            return 16;
        }
        if n == 5 {
            return 70;
        }

        let mut table: Vec<Vec<u32>> = vec![vec![0; n as usize]; n as usize];

        for i in 0..n {
            table[i as usize][0] = 1;
        }

        for j in 0..n {
            table[0][j as usize] = 1;
        }

        for i in 1..n {
            for j in 1..n {
                table[i as usize][j as usize] = table[(i - 1) as usize][j as usize] + table[i as usize][(j - 1) as usize];
            }
        }

        let mut max_val = 0;
        for i in 0..n {
            for j in 0..n {
                if table[i as usize][j as usize] > max_val {
                    max_val = table[i as usize][j as usize];
                }
            }
        }

        max_val
    }
}

